package com.autoops.command.service;import com.autoops.command.validation.CommandParameterValidator;import org.springframework.stereotype.Service;import java.util.Map;@Service public class SafeCommandResolver{private final CommandParameterValidator validator;public SafeCommandResolver(CommandParameterValidator v){validator=v;}public String resolve(String template,Map<String,String> params){validator.validate(params);String out=template;for(var e:params.entrySet())out=out.replace("{{"+e.getKey()+"}}",shellQuote(e.getValue()));if(out.contains("{{"))throw new IllegalArgumentException("Missing command parameter");return out;}private String shellQuote(String s){return "'"+s.replace("'","'\"'\"'")+"'";}}
